-- 0006_admin_operations.sql -- Already applied to the live database; idempotent (create or replace / revoke / grant), -- so it can be committed to drizzle/migrations and replayed safely on a fresh database. -- 1) Nobody becomes admin automatically any more. Every new account gets the 'user' role. -- Admins are granted manually: insert into public.user_roles (user_id, role) values ('<uuid>', 'admin'); create or replace function public.handle_new_user_role() returns trigger language plpgsql security definer set search_path to 'public' as $$ begin insert into public.user_roles (user_id, role) values (new.id, 'user') on conflict (user_id, role) do nothing; return new; end $$; -- 2) Public-readable site settings allow-list: 'general' (unchanged) and a new 'toggles' key -- whose value must be an object containing ONLY boolean values (on/off switches). create or replace function public.is_public_site_setting(setting_key text, setting_value jsonb) returns boolean language sql immutable set search_path to 'public' as $$ select coalesce( case setting_key when 'general' then jsonb_typeof(setting_value) = 'object' and setting_value - array['hero_title_fa','hero_title_en','hero_desc_fa','hero_desc_en','about_fa','about_en','telegram_support','telegram_channel','email','instagram','website']::text[] = '{}'::jsonb when 'toggles' then jsonb_typeof(setting_value) = 'object' and not exists ( select 1 from jsonb_each(case when jsonb_typeof(setting_value) = 'object' then setting_value else '{}'::jsonb end) e where jsonb_typeof(e.value) <> 'boolean' ) else false end, false); $$; -- 3) Admin-only customer list (emails live in auth.users, which the client cannot read). create or replace function public.admin_list_customers() returns table ( id uuid, email text, display_name text, created_at timestamptz, last_sign_in_at timestamptz, orders_count bigint, active_licenses_count bigint ) language plpgsql stable security definer set search_path = public, auth as $$ begin if not public.has_role(auth.uid(), 'admin'::public.app_role) then raise exception 'not authorized' using errcode = '42501'; end if; return query select u.id, u.email::text, p.display_name, u.created_at, u.last_sign_in_at, (select count(*) from public.orders o where o.user_id = u.id), (select count(*) from public.licenses l where l.user_id = u.id and l.status = 'active' and l.expires_at > now()) from auth.users u left join public.profiles p on p.id = u.id order by u.created_at desc; end $$; revoke all on function public.admin_list_customers() from public, anon; grant execute on function public.admin_list_customers() to authenticated;